import type { Content } from '@/shared/contracts';
import RichText from '@/components/RichText';
/** Scoring is displayed with its answer candidate, not generated by the view. */
export function ScoringPreview({ question }: { question: Content['question'] }) {
  if (!question) return null;
  const leaves = question.children.length ? question.children : [question];
  return leaves.map((leaf, index) =>
    !leaf.grading?.rubric.length ? null : (
      <section key={index} className="answer-block">
        <p>
          {question.children.length ? `小题 ${index + 1} · ` : ''}得分点 · 共{' '}
          {leaf.grading.defaultScore} 分
        </p>
        <ol>
          {leaf.grading.rubric.map((item) => (
            <li key={item.rubricItemKey}>
              <span>{item.maxScore} 分</span>
              <RichText text={item.criteria} />
            </li>
          ))}
        </ol>
      </section>
    ),
  );
}
